def test_warns_pydantic_v1_model_in_endpoint_param() -> None:
    class ParamModelV1(BaseModel):
        name: str

    app = FastAPI()

    with pytest.warns(
        DeprecationWarning,
        match=r"pydantic\.v1 is deprecated.*Please update the param data:",
    ):

        @app.post("/param")
        def endpoint(data: ParamModelV1):
            return data

    client = TestClient(app)
